const D = { scale:1, energy:.65, hue:315, speed:1, density:.5, x:.5, y:.62, chub:.5, tail:.5, jaw:.5, pose:'stomp', style:'neon', act:'party', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const m = u * P.scale;
const L = (a,b,t)=>a+(b-a)*t;
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const fr = i => { const v = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return v - Math.floor(v); };
const TAU = Math.PI*2;
const sty = P.style;
const hi = P.hue, rim = (P.hue+165)%360;
const sw = u*0.006*P.scale;

if (S.seedUsed !== P.seed){ S.seedUsed=P.seed; S.tear=[]; for(let i=0;i<5;i++) S.tear.push({y:fr(i+2), h:.02+fr(i+6)*.03, o:fr(i+9)}); }

// ---- clock ----
if (S.lastBeat==null || K.beat < S.lastBeat) S.lastBeat=K.beat;
S.lastBeat=K.beat;
const bt = K.beat*P.speed;
const en = P.energy;
const pulse = K.pulse;
const kick = clamp(pulse*.9 + A.bass*.7, 0, 1.4);
const pose=P.pose, chub=P.chub;

// roar act — periodic build + big roar every 8 beats
let roar=0;
if (P.act==='roar'){ const rc=(bt%8)/8; roar=Math.pow(Math.max(0,Math.sin(rc*Math.PI)),3); }
let jawOpen = .12 + kick*.22*en + roar*.75 + (pose==='idle'?0:0);
jawOpen = clamp(jawOpen*L(.7,1.3,P.jaw), 0, 1);

// choreography weights per pose
const stompW = pose==='stomp'?1 : pose==='strut'?.35 : pose==='idle'?.25 : .6;
const pumpW  = pose==='fistpump'?1 : pose==='idle'?.15 : .5;
const bob = (kick*.03 + roar*.04) * en * stompW;           // body drop on beat
const shake = Math.sin(K.t*95)*pulse*0.012*en*stompW;      // screen-shake feel
const squashY = 1 - kick*.06*en*stompW;
const squashX = 1 + kick*.045*en*stompW;

const px=P.x*width, py=P.y*height;

// ---- style-aware tube renderer ----
function tube(fn, filled){
  if (sty==='wireframe'){ noFill(); stroke(hi,80,100,95); strokeWeight(sw*.7); fn(); return; }
  if (sty==='chrome'){
    if (filled!==false){ noStroke(); fill(hi,26,66); fn(); }
    noStroke(); return;
  }
  // neon + vhs : dark glassy fill, then layered glow strokes (cheap, no shadowBlur)
  if (filled!==false){ noStroke(); fill(hi,72,11,96); fn(); }
  noFill();
  if (sty==='vhs'){ push(); translate(-sw*.9,0); stroke(0,85,100,45); strokeWeight(sw*1.1); fn(); pop();
                    push(); translate(sw*.9,0); stroke(180,80,100,45); strokeWeight(sw*1.1); fn(); pop(); }
  stroke(hi,85,100,20); strokeWeight(sw*3.4); fn();   // outer glow
  stroke(rim,65,100,85); strokeWeight(sw*1.4); fn();  // cyan rim
  stroke(hi,88,100,100); strokeWeight(sw*.7); fn();   // bright core
}
function chromeHi(fn){ if(sty==='chrome'){ noStroke(); fill(hi,10,96,55); fn(); } }

push();
translate(px + shake*m, py + bob*m);
scale(squashX, squashY);

// ============ TAIL (behind, sways counter to legs) ============
const tailSway = Math.sin(bt*Math.PI)*.22*en + roar*.1;
const tl = m*L(.42,.72,P.tail);
push(); translate(-m*.14, m*.02); rotate(tailSway);
tube(()=>{ beginShape();
  vertex(0,-m*.11); vertex(-tl*.5,-m*.05);
  vertex(-tl,-m*.005); vertex(-tl,m*.02);
  vertex(-tl*.5,m*.06); vertex(0,m*.12);
  endShape(CLOSE); });
pop();

// ============ LEGS (alternate stomp) ============
for (const s of [1,-1]){
  const lift = Math.sin(bt*Math.PI + (s>0?0:Math.PI));
  const up = Math.max(0,lift)*m*.06*en*stompW;
  const hipX=s*m*.05, hipY=m*.10;
  const kneeX=hipX+s*m*.02, kneeY=m*.20-up*.4;
  const ftY=m*.30-up;
  push();
  tube(()=>{ beginShape();
    vertex(hipX-m*.07,hipY); vertex(hipX+m*.08,hipY);
    vertex(kneeX+m*.055,kneeY); vertex(kneeX-m*.05,kneeY);
    endShape(CLOSE); });
  // shin + clawed foot
  tube(()=>{ ellipse(kneeX,(kneeY+ftY)/2, m*.09, ftY-kneeY+m*.03); });
  tube(()=>{ beginShape();
    vertex(kneeX-m*.05,ftY-m*.02); vertex(kneeX+m*.14,ftY-m*.02);
    vertex(kneeX+m*.15,ftY+m*.03); vertex(kneeX-m*.05,ftY+m*.03);
    endShape(CLOSE); });
  pop();
}

// ============ TORSO ============
tube(()=>{ beginShape();
  const w=m*L(.16,.22,chub);
  vertex(-m*.16,-m*.02);
  bezierVertex(-m*.02,-m*.20, m*.14,-m*.18, m*.18,-m*.02);
  bezierVertex(m*.20,w, m*.02,m*.20, -m*.10,m*.15);
  bezierVertex(-m*.20,m*.10, -m*.22,m*.02, -m*.16,-m*.02);
  endShape(CLOSE); });
chromeHi(()=>{ ellipse(-m*.02,-m*.08,m*.24,m*.16); });

// ---- dorsal neon scutes along the back (count by density) ----
const nsc = 3 + Math.round(P.density*6);
for (let i=0;i<nsc;i++){ const tt=i/(nsc-1);
  const bx = L(-m*.14, m*.10, tt), by = L(-m*.02,-m*.16, tt) - Math.sin(tt*Math.PI)*m*.05;
  const h = m*(.03+ .02*Math.sin(tt*Math.PI)) * (1+kick*.25*en);
  push(); translate(bx,by);
  tube(()=>{ triangle(-m*.02,0, m*.02,0, 0,-h); }, false);
  pop(); }

// ============ TINY ARMS (fist pump) ============
const pump = (Math.max(0,Math.sin(bt*Math.PI))* .9 + kick*.3) * pumpW;
for (const s of [0,1]){
  const ax=m*.10 - s*m*.02, ay=-m*.02 + s*m*.02;
  const fistY = ay - m*.02 - pump*m*.11;
  const fistX = ax + m*.09;
  push();
  tube(()=>{ ellipse((ax+fistX)/2,(ay+fistY)/2, m*.11, m*.05); });
  tube(()=>{ ellipse(fistX,fistY, m*.06,m*.06); });
  pop();
}

// ============ NECK + HEAD (bob + nod) ============
const nod = Math.sin(bt*Math.PI*.5)*.05 + kick*.06*en - roar*.12;
push();
translate(m*.12,-m*.10); rotate(nod);
// neck
tube(()=>{ beginShape();
  vertex(-m*.06,m*.12); vertex(-m*.02,m*.12);
  vertex(m*.10,-m*.04); vertex(m*.02,-m*.06);
  endShape(CLOSE); });
// head (skull + snout)
tube(()=>{ beginShape();
  vertex(-m*.04,-m*.08); vertex(m*.14,-m*.09);
  vertex(m*.26,-m*.04); vertex(m*.27,m*.0);
  vertex(m*.14,m*.02); vertex(-m*.02,m*.02);
  endShape(CLOSE); });
chromeHi(()=>{ ellipse(m*.08,-m*.05,m*.16,m*.06); });

// lower jaw — opens by jawOpen
push(); translate(m*.05,m*.015); rotate(jawOpen*.6);
tube(()=>{ beginShape();
  vertex(-m*.02,0); vertex(m*.22,-m*.005);
  vertex(m*.2,m*.055); vertex(-m*.01,m*.05);
  endShape(CLOSE); });
// lower teeth
if (sty!=='wireframe'){ noStroke(); fill(0,0,98,90);
  for(let i=0;i<4;i++){ const tx=m*.02+i*m*.045; triangle(tx,-m*.002, tx+m*.018,-m*.002, tx+m*.009,-m*.03);} }
pop();
// upper teeth
if (sty!=='wireframe'){ noStroke(); fill(0,0,98,90);
  for(let i=0;i<4;i++){ const tx=m*.03+i*m*.05; triangle(tx,m*.01, tx+m*.02,m*.01, tx+m*.01,m*.04);} }

// nostril
if (sty!=='wireframe'){ noStroke(); fill(hi,80,40); ellipse(m*.24,-m*.03,m*.02,m*.03); }

// ---- sunglasses (neon shades) ----
push(); translate(m*.06,-m*.055);
if (sty==='wireframe'){ noFill(); stroke(hi,80,100,95); strokeWeight(sw*.7); }
else { noStroke(); fill(P.hue,90,14); }
for (const s of [0,1]){ push(); translate(s*m*.09,0);
  if(sty!=='wireframe'){ fill(P.hue,90,12); } rect(0,0,m*.085,m*.05,m*.01); pop(); }
// bridge
if(sty!=='wireframe'){ noStroke(); fill(P.hue,90,14);} rect(m*.085,-m*.005,m*.02,m*.012);
// neon frame + glint
noFill(); stroke(rim,70,100,95); strokeWeight(sw*.7);
for (const s of [0,1]){ push(); translate(s*m*.09,0); rect(0,0,m*.085,m*.05,m*.01); pop(); }
// specular slash
stroke(0,0,100,90); strokeWeight(sw*.6);
const gl = (K.t*.6)%1; line(-m*.03+gl*m*.02,-m*.02, -m*.05+gl*m*.02,m*.02);
pop();
pop(); // head

// ============ ROAR RINGS ============
if (roar>0.15 && sty!=='wireframe'){
  push(); translate(m*.42,-m*.20); noFill();
  for(let i=0;i<3;i++){ const rr=(roar - i*.2); if(rr>0){ stroke(hi,80,100, rr*70);
    strokeWeight(sw*(2-i*.5)); const rad=m*(.08+ (1-rr+i*.15)*.5); arc(0,0,rad,rad,-1.0,1.0);} }
  pop();
}

pop(); // subject transform

// ============ NEON GROUND LINE + reflection ============
if (sty!=='wireframe'){
  const gy = py + m*.30;
  push();
  stroke(hi,85,100,22); strokeWeight(sw*3); line(px-m*.45,gy, px+m*.5,gy);
  stroke(rim,70,100,80); strokeWeight(sw*.8); line(px-m*.45,gy, px+m*.5,gy);
  // soft reflected glow puddle under feet, pulses with beat
  noStroke(); fill(hi,80,60, 10+kick*14*en); ellipse(px+m*.02,gy+m*.03, m*.7, m*.09*(1+kick*.4));
  pop();
}

// ============ SCANLINES / VHS TEAR (over body region) ============
if (sty==='neon' || sty==='vhs'){
  push(); noStroke();
  const y0=py-m*.34, y1=py+m*.30, step=Math.max(3, u*0.012);
  fill(0,0,0,14);
  for(let y=y0;y<y1;y+=step) rect(px-m*.55, y, m*1.1, step*.5);
  if (sty==='vhs'){ for(const t of S.tear){ const ty=y0+(t.y*(y1-y0)); const off=Math.sin(bt*Math.PI + t.o*TAU)*m*.03*en;
    fill(180,70,100,30); rect(px-m*.55+off, ty, m*1.1, t.h*m*.4);
    fill(0,85,100,25); rect(px-m*.55-off, ty, m*1.1, t.h*m*.4); } }
  pop();
}
